<script lang="ts">
  import { onMount } from 'svelte';
  import { getInventoryState, loadInventory, selectInventoryItem, saveInventoryConfig, submitInventoryOperation } from '../stores/inventory.store.svelte';
  let state = getInventoryState();
  let operation = $state<'purchase' | 'sale'>('purchase');
  let quantity = $state('1');
  let unitCost = $state('0');
  let salePrice = $state('0');
  let minimumStock = $state('0');
  let fulfillment = $state<'owned_stock' | 'managed_sale'>('owned_stock');
  let commission = $state('0');
  let supplier = $state('');
  let availability = $state<'available' | 'unavailable' | 'unknown'>('unknown');
  const syncForm = () => { if (!state.selected) return; fulfillment = state.selected.fulfillmentModel; commission = String(state.selected.commissionPercent); supplier = state.selected.supplierName ?? ''; availability = state.selected.externalAvailability; minimumStock = String(state.selected.minimumStock); unitCost = String(state.selected.acquisitionCost); salePrice = String(state.selected.price ?? 0); };
  async function changeSelection(id: string) { selectInventoryItem(id); syncForm(); }
  async function saveSupply() { const min = Number(minimumStock), commissionValue = Number(commission); if (!state.selected || state.selected.type !== 'product') return; if (!Number.isFinite(min) || min < 0 || !Number.isFinite(commissionValue) || commissionValue < 0 || commissionValue > 100) { return; } await saveInventoryConfig({ fulfillmentModel: fulfillment, minimumStock: min, commissionPercent: commissionValue, supplierName: supplier.trim() || null, externalAvailability: availability }); }
  async function submitOperation() { const qty = Number(quantity), cost = Number(unitCost), price = Number(salePrice); if (!state.selected || state.selected.type !== 'product' || !Number.isFinite(qty) || qty <= 0) return; if (operation === 'purchase' && (!Number.isFinite(cost) || cost < 0)) return; if (operation === 'sale' && (!Number.isFinite(price) || price < 0)) return; await submitInventoryOperation(operation, qty, cost, price); }
  onMount(async () => { await loadInventory(); syncForm(); });
</script>
<svelte:head><title>Inventario y ventas | SOLUX</title></svelte:head>
<div class="page"><header><div><p class="eyebrow">Backoffice / Finanzas</p><h1>Inventario y ventas</h1><p class="muted">Stock propio, productos gestionados y operaciones registradas.</p></div><button class="secondary" onclick={loadInventory} disabled={state.loading}>Actualizar</button></header>
  {#if state.error}<p class="alert" role="alert">{state.error}</p>{/if}{#if state.notice}<p class="notice" role="status">{state.notice}</p>{/if}
  <div class="stats"><article><span>Productos</span><strong>{state.items.filter((i) => i.type === 'product').length}</strong></article><article><span>Stock bajo</span><strong>{state.lowStock.length}</strong></article><article><span>Venta gestionada</span><strong>{state.items.filter((i) => i.type === 'product' && i.fulfillmentModel === 'managed_sale').length}</strong></article></div>
  <section class="panel"><h2>Producto</h2>{#if state.loading}<p>Cargando catálogo…</p>{:else}<label>Seleccionar producto<select value={state.selectedId} onchange={(e) => changeSelection(e.currentTarget.value)}>{#each state.items.filter((i) => i.type === 'product') as item}<option value={item.id}>{item.name}{item.isActive ? '' : ' (inactivo)'}</option>{/each}</select></label>{#if state.selected}<div class="metrics"><div><span>Stock</span><strong>{state.selected.stockQuantity}</strong></div><div><span>Costo promedio</span><strong>{state.selected.averageCost.toFixed(2)} {state.selected.currency}</strong></div><div><span>Precio de venta</span><strong>{state.selected.price ?? 'A consultar'} {state.selected.price != null ? state.selected.currency : ''}</strong></div></div><div class="form-grid"><label>Modelo de suministro<select bind:value={fulfillment}><option value="owned_stock">Stock propio</option><option value="managed_sale">Venta gestionada</option></select></label><label>Stock mínimo<input type="number" min="0" step="0.001" bind:value={minimumStock} /></label>{#if fulfillment === 'managed_sale'}<label>Proveedor interno<input bind:value={supplier} placeholder="Nombre del proveedor" /></label><label>Comisión Solux (%)<input type="number" min="0" max="100" step="0.001" bind:value={commission} /></label><label>Disponibilidad externa<select bind:value={availability}><option value="available">Disponible</option><option value="unavailable">No disponible</option><option value="unknown">Desconocida</option></select></label>{/if}</div><button onclick={saveSupply} disabled={state.saving}>{state.saving ? 'Guardando…' : 'Guardar configuración'}</button><p class="muted">Proveedor, comisión y modelo de suministro son datos internos; no aparecen en catálogo público.</p>{:else}<p>{state.items.some((item) => item.type === 'product') ? 'Selecciona un producto.' : 'No hay productos en catálogo.'}</p>{/if}{/if}</section>
  {#if state.selected}<section class="panel"><h2>Registrar operación</h2><div class="form-grid"><label>Operación<select bind:value={operation}><option value="purchase" disabled={state.selected.fulfillmentModel === 'managed_sale'}>Entrada por compra</option><option value="sale">Venta</option></select></label><label>Cantidad<input type="number" min="0.001" step="0.001" bind:value={quantity} /></label>{#if operation === 'purchase'}<label>Costo unitario<input type="number" min="0" step="0.01" bind:value={unitCost} /></label>{:else}<label>Precio unitario de venta<input type="number" min="0" step="0.01" bind:value={salePrice} /></label>{/if}</div><button onclick={submitOperation} disabled={state.saving || (operation === 'purchase' && state.selected.fulfillmentModel === 'managed_sale')}>{state.saving ? 'Procesando…' : operation === 'purchase' ? 'Registrar compra y entrada' : 'Registrar venta'}</button>{#if operation === 'sale' && state.selected.fulfillmentModel === 'managed_sale'}<p class="muted">La venta crea comisión y saldo de proveedor. No descuenta stock propio.</p>{/if}</section>{/if}
  <section class="panel"><h2>Alertas de stock</h2>{#if state.lowStock.length === 0}<p class="muted">Sin productos bajo mínimo.</p>{:else}<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Stock</th><th>Mínimo</th></tr></thead><tbody>{#each state.lowStock as item}<tr><td>{item.name}</td><td>{item.stockQuantity}</td><td>{item.minimumStock}</td></tr>{/each}</tbody></table></div>{/if}</section>
</div>
<style>.page{padding:clamp(20px,4vw,40px);max-width:1200px;margin:0 auto;color:var(--color-text)}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{font-size:clamp(26px,3vw,36px);margin:4px 0 8px}h2{font-size:18px;margin:0 0 18px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--color-primary);font-weight:800;margin:0}.muted{color:var(--color-muted);font-size:13px;line-height:1.5}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:16px}.stats article,.metrics>div{padding:16px;border:1px solid var(--color-border);border-radius:12px;display:flex;flex-direction:column;gap:8px}.stats span,.metrics span{font-size:12px;color:var(--color-muted)}.stats strong,.metrics strong{font-size:22px}.panel{background:var(--color-surface);border:1px solid var(--color-border);border-radius:14px;padding:22px;margin-bottom:16px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:650}input,select{width:100%;min-width:0;padding:10px 12px;border:1px solid var(--color-border);border-radius:8px;background:var(--color-background);color:var(--color-text)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}button{border:0;border-radius:8px;padding:11px 16px;background:var(--color-primary);color:white;font-weight:750;cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}.secondary{background:var(--color-surface-2);color:var(--color-text);border:1px solid var(--color-border)}.alert,.notice{padding:12px 14px;border-radius:8px;margin:0 0 16px;font-size:13px}.alert{background:#fee2e2;color:#991b1b}.notice{background:#dcfce7;color:#166534}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:11px;border-bottom:1px solid var(--color-border);font-size:13px}@media(max-width:680px){header{align-items:flex-start;flex-direction:column}.stats,.metrics{grid-template-columns:1fr}.form-grid{grid-template-columns:1fr}}</style>
